// Capture and format error diagnostics
const errorData = $input.item.json;

const failedWorkflow = errorData.workflow?.name || 'Unknown Workflow';
const failedNode = errorData.execution?.lastNodeExecuted || 'Unknown Node';
const errorMessage = errorData.execution?.error?.message || 'No detailed error message provided';
const executionId = errorData.execution?.id || 'N/A';
const timestamp = new Date().toISOString();

console.error(`[LendLoop CRITICAL ERROR] Workflow '${failedWorkflow}' failed at node '${failedNode}'`);
console.error(`Execution ID: ${executionId}`);
console.error(`Error Details: ${errorMessage}`);

return [{
  json: {
    alertLevel: 'CRITICAL',
    service: 'LendLoop-Automation',
    workflow: failedWorkflow,
    failedNode,
    errorMessage,
    executionId,
    timestamp,
    actionRequired: 'Investigate node configuration, network connectivity, or invalid payload structure.'
  }
}];

// Administrative notification sink (can connect to Slack, PagerDuty, or Sentry)
const alert = $input.item.json;

console.log('[LendLoop Admin Alert Dispatched]');
console.log(JSON.stringify(alert, null, 2));

return [{
  json: {
    alertLogged: true,
    status: 'recorded',
    executionId: alert.executionId
  }
}];
